function filtered(){const mode=el('map-class').value,bCutoff=Number(el('map-b-cutoff').value);return stations.filter(s=>(el('map-province').value==='all'||s.province===el('map-province').value)&&(mode==='all'||(s.class===mode&&(mode!=='B'||s.score>bCutoff))));}
function drawPoints(fit=false){pointLayer.clearLayers();markers.clear();const list=filtered();for(const s of list){const color={A:'#2664cf',B:'#007f81',C:'#c98a23'}[s.class],m=L.marker([s.lat,s.lon],{icon:L.divIcon({className:'station-marker'+(s.id===selectedId?' selected':''),html:`<span class="station-dot" style="--dot:${color}"></span>`,iconSize:[18,18],iconAnchor:[9,9]}),title:s.displayName,alt:s.displayName,keyboard:true});m.bindTooltip(document.createTextNode(`${s.displayName} · Class ${s.class}`),{direction:'top',offset:[0,-12]});m.on('click',()=>openStation(s.id));m.addTo(pointLayer);markers.set(s.id,m);}el('map-count').textContent=`${list.length} / 85 จุด`;if(fit&&list.length){map.stop();map.fitBounds(L.latLngBounds(list.map(s=>[s.lat,s.lon])),{padding:[36,36],maxZoom:12,animate:false});}if(selectedId&&!list.some(s=>s.id===selectedId))closeDetail();}
