const scoreValue=v=>Number.isFinite(Number(v))?Number(v).toFixed(2):'ไม่มีข้อมูล';
function scoreParts(s){const v=s.scores||{},N=Number(v.N),O=Number(v.O),P=Number(v.P),Q=Number(v.Q),M=Number(s.score);if(![N,O,P,Q,M].every(Number.isFinite))return null;const direct=.50*O+.15*Q+.20*N+.15*P,swapped=.50*N+.15*Q+.20*O+.15*P,useSwapped=Math.abs(swapped-M)<Math.abs(direct-M);return {network:useSwapped?N:O,networkKey:useSwapped?'N':'O',slope:useSwapped?O:N,slopeKey:useSwapped?'O':'N',relief:P,elevation:Q,total:useSwapped?swapped:direct};}
function scoreCalculation(s){const x=scoreParts(s);if(!x)return '';return `<p class="score-calculation"><strong>คำนวณจากปัจจัย: ${scoreValue(x.total)} /100</strong><br>${scoreValue(x.total)} = (0.50×${scoreValue(x.network)}) + (0.15×${scoreValue(x.elevation)}) + (0.20×${scoreValue(x.slope)}) + (0.15×${scoreValue(x.relief)})<br><small>Network Gap (${x.networkKey}) · Elevation Difference (Q) · Slope (${x.slopeKey}) · Local Relief (P)</small></p>`;}
const detailValue=v=>typeof v==='number'?v.toLocaleString('th-TH',{maximumFractionDigits:3}):esc(String(v));
function additionalDetails(s){const d=s.details||{},fields=[['slopeDeg','ความลาดชัน','องศา'],['nearestStationCode','รหัสสถานีใกล้เคียง',''],['nearestStationName','ชื่อสถานีใกล้เคียง',''],['nearestStationDistanceKm','ระยะห่างสถานีใกล้เคียง','กม.'],['demElevationScore','คะแนนระดับความสูง DEM','ม.'],['nearestDemElevationM','ความสูง DEM สถานีใกล้เคียง','ม.'],['demElevationDifferenceM','ความต่างระดับ DEM ของสถานีและสถานีใกล้เคียง','ม.'],['localRelief90m','ความต่างระดับภูมิประเทศในรัศมี 90 ม.','ม.']].filter(([key])=>d[key]!==undefined&&d[key]!==null&&d[key]!=='');if(!fields.length)return '';return `<details class="additional-details"><summary>รายละเอียดเพิ่มเติม <span>${fields.length} รายการ</span></summary><p>ค่าจาก Excel เพื่ออ่านบริบทภูมิประเทศและสถานีอ้างอิง</p><div class="additional-detail-grid">${fields.map(([key,label,unit])=>`<div><span>${label}</span><strong>${detailValue(d[key])}${unit?` <small>${unit}</small>`:''}</strong></div>`).join('')}</div></details>`;}
function spatialReasonCard(s){if(!s.spatialReason)return '';return `<details class="spatial-reason"><summary>เหตุผลเชิงพื้นที่ <span>เชื่อมโยงหมู่บ้าน</span></summary><div class="spatial-reason-body">${esc(s.spatialReason)}</div><p>ที่มา: ข้อความเหตุผลเชิงพื้นที่ที่แนบมา จับคู่ด้วยชื่อสถานี</p></details>`;}
async function openStation(id){const s=stations.find(s=>s.id===id);if(!s)return;const sc=s.scores||{},parts=scoreParts(s),formula=scoreCalculation(s);selectedId=id;const token=++selectionToken;drawPoints();el('map-detail').innerHTML=`<button class="close-detail" aria-label="ปิดรายละเอียด">×</button><span class="class-badge ${s.class}">Class ${s.class}</span><h3>${esc(s.displayName)}</h3><p>ต.${esc(s.subdistrict)} อ.${esc(s.district)}<br>จ.${esc(s.province)}</p><div class="position">${s.lat}, ${s.lon}<br>พื้นที่สี${esc(s.zone)} · สถานี${esc(s.status)}</div><div class="score-breakdown" aria-label="รายละเอียดคะแนนจาก Excel"><strong>รายละเอียดคะแนนจาก Excel</strong><div><span>คะแนนความเหมาะสมเชิงพื้นที่รวม</span><b>${scoreValue(s.score)} /100</b></div>${formula}<div><span>คะแนนความลาดชัน (${parts?.slopeKey||'N'})</span><b>${scoreValue(parts?.slope??sc.N)}</b></div><div><span>คะแนนช่องว่างโครงข่าย (${parts?.networkKey||'O'})</span><b>${scoreValue(parts?.network??sc.O)}</b></div><div><span>คะแนนความซับซ้อนของภูมิประเทศ (P)</span><b>${scoreValue(parts?.relief??sc.P)}</b></div><div><span>คะแนนความต่างระดับความสูง (Q)</span><b>${scoreValue(parts?.elevation??sc.Q)}</b></div></div>${additionalDetails(s)}${spatialReasonCard(s)}<div id="map-gallery" class="map-gallery"><div class="photo-frame"><div class="photo-empty">กำลังโหลดรูปภาพ…</div></div></div><a class="outline" href="master.html?station=${s.id}">จัดการข้อมูล / แนบรูป ↗</a><p class="note">Excel: ${esc(s.source)} แถว ${s.row} · M–Q</p>`;el('map-detail').querySelector('.close-detail').onclick=closeDetail;
 try{const detail=await api('/api/stations/'+id);if(token!==selectionToken)return;mountGallery(el('map-gallery'),detail.photos);if(detail.notes){const p=document.createElement('p');p.textContent=detail.notes;p.className='note';el('map-detail').append(p);}}
 catch(e){if(token===selectionToken)el('map-gallery').innerHTML=`<div class="notice error-text">${esc(e.message)}<br><button class="outline" id="retry-photos">ลองโหลดรูปใหม่</button></div>`;el('retry-photos')?.addEventListener('click',()=>openStation(id));}
}
async function geo(key,params,signal){let features=[],offset=0;for(let page=0;page<12;page++){const q=new URLSearchParams({...params,offset});const data=await api('/api/gis/'+key+'?'+q,{signal});features.push(...data.features);if(data.nextOffset==null)return {type:'FeatureCollection',features};if(data.nextOffset<=offset)throw Error('บริการส่งข้อมูลซ้ำ กรุณาซูมเข้า');offset=data.nextOffset;}throw Error('ชั้นข้อมูลมีจำนวนมาก กรุณาซูมเข้าเพื่อแสดงให้ครบ');}
