async function loadLayers(){const token=++loadToken;controller?.abort();controller=new AbortController();const signal=controller.signal,p=el('map-province').value,b=map.getBounds(),zoom=map.getZoom(),params={bbox:[b.getWest(),b.getSouth(),b.getEast(),b.getNorth()].join(','),province:p,provinces:stationProvinces.join('|'),tolerance:String(Math.max(0.00001,0.003/2**(zoom-7)))};
 let failures=[];await Promise.all(config.map(async c=>{const state=el('state-'+c.id);state.className='';if(layers.has(c.id)){map.removeLayer(layers.get(c.id));layers.delete(c.id);}const enabled=document.querySelector(`[data-layer="${c.id}"]`).checked;if(!enabled){state.textContent='ปิด';return;}if(zoom<c.min){state.textContent='ซูมเข้าอย่างน้อย '+c.min;return;}state.textContent='กำลังโหลด…';try{const scope=provinceScopedLayers.has(c.id)?{province:p,provinces:stationProvinces.join('|'),tolerance:params.tolerance}:params;const data=await geo(c.id,c.id==='province'?{province:p,provinces:stationProvinces.join('|'),tolerance:'0.002'}:scope,signal);if(token!==loadToken)return;const rainfall=c.id==='rainfall',risk=c.id==='risk',flow=c.id==='flow',visibleData=risk?{...data,features:data.features.filter(f=>['1','3'].includes(String(f.properties?.score_1)))}:data;const shapes=L.geoJSON(visibleData,{pane:risk?'risk':(rainfall?'rainfall':(flow?'flow':(c.id==='major'||c.id==='minor'?'hydro':'boundary'))),interactive:rainfall||risk||flow,style:feature=>{if(risk){const shared=String(feature.properties?.score_1)==='3';return {color:'#fff',weight:.7,opacity:.9,fill:true,fillColor:shared?'#ed1616':'#f5a400',fillOpacity:shared?.72:.62};}if(rainfall){const fresh=feature.properties?.class==='every day',color=fresh?'#16c83d':'#f12525';return {color:'#fff',weight:2,opacity:1,fill:true,fillColor:color,fillOpacity:1};}const boundary=c.id==='province'||c.id==='district'||c.id==='subdistrict';return {color:boundary?'#fff':c.color,weight:c.id==='province'?2.6:c.id==='district'?1.35:c.id==='subdistrict'?0.7:c.id==='major'?2.4:1,opacity:boundary?0.95:0.85,fill:false};},pointToLayer:(feature,latlng)=>{const props=feature.properties||{};if(flow){const angle=Number(props.DIRECTION)||0;return L.marker(latlng,{pane:'flow',icon:L.divIcon({className:'flow-marker',html:`<span style="transform:rotate(${angle}deg)"></span>`,iconSize:[16,12],iconAnchor:[8,6]})});}const fresh=props.class==='every day',color=fresh?'#16c83d':'#f12525';return L.circleMarker(latlng,{pane:'rainfall',className:'rainfall-marker',radius:4,color:'#fff',weight:1.5,opacity:1,fillColor:color,fillOpacity:1});},onEachFeature:(feature,featureLayer)=>{const d=feature.properties||{};if(flow){const degrees=((Number(d.DIRECTION)||0)%360+360)%360,direction={0:'เหนือ',45:'ตะวันออกเฉียงเหนือ',90:'ตะวันออก',135:'ตะวันออกเฉียงใต้',180:'ใต้',225:'ตะวันตกเฉียงใต้',270:'ตะวันตก',315:'ตะวันตกเฉียงเหนือ'}[degrees]||`${degrees}°`;featureLayer.bindTooltip(`<strong>ทิศทางน้ำ</strong><br>ไหลไปทาง${direction}<br>ต.${esc(d.TAM_NAM_T||'-')} อ.${esc(d.AMP_NAM_T||'-')} จ.${esc(d.PROV_NAM_T||'-')}`,{sticky:true,direction:'top'});}if(rainfall){const fresh=d.class==='every day',raw=d.class||'ไม่มีข้อมูล';featureLayer.bindTooltip(`<strong>${esc(d.station_display_name||d.station_id||'สถานีหน่วยงานอื่น')}</strong><br><span style="color:${fresh?'#16c83d':'#f12525'}">●</span> ${fresh?'จุดทึบสีเขียว · อัปเดตทุกวัน':'จุดทึบสีแดง · คุณภาพต่ำ / ไม่อัปเดตทุกวัน'}<br>รอบข้อมูล: ${esc(raw)}<br>จังหวัด: ${esc(d.prov_nam_t||'-')}<br>วันที่ข้อมูล: ${esc(d.data_dt||'-')}`,{sticky:true,direction:'top'});}if(risk){const shared=String(d.score_1)==='3';featureLayer.bindTooltip(`<strong>${esc(d.tam_nam_t||'พื้นที่เสี่ยง')}</strong><br><span style="color:${shared?'#ed1616':'#f5a400'}">●</span> ${shared?'สีแดง · ปภ.ส่วนกลาง + ปภ.จังหวัดเห็นตรงกัน':'สีส้ม · พื้นที่เสี่ยง ปภ.จังหวัด'}<br>อ.${esc(d.amp_nam_t||'-')} จ.${esc(d.prov_nam_t||'-')}<br>ภัย: ${esc(d.สาธารณภัย||'-')}`,{sticky:true,direction:'top'});}}});let layer=shapes;if(c.id==='province'){const wanted=new Set(p==='all'?stationProvinces:[p]),labels=L.layerGroup();shapes.eachLayer(featureLayer=>{const props=featureLayer.feature?.properties||{},name=props.PROV_NAM_T||props.prov_nam_t;if(!name||!wanted.has(name)||!featureLayer.getBounds)return;L.marker(featureLayer.getBounds().getCenter(),{pane:'province-label',interactive:false,icon:L.divIcon({className:'province-label',html:`<span>${esc(name)}</span>`,iconSize:null})}).addTo(labels);});layer=L.layerGroup([shapes,labels]);}layer.addTo(map);layers.set(c.id,layer);state.textContent=(risk?visibleData.features.length:data.features.length)+' รายการ';}catch(e){if(token!==loadToken)return;state.textContent='โหลดไม่สำเร็จ';state.className='layer-error';failures.push(c.name+': '+e.message);}}));if(token!==loadToken)return;el('map-layer-status').textContent=failures.length?failures.join(' · '):`แสดงชั้นข้อมูลเฉพาะ ${stationProvinces.length} จังหวัดที่มีจุดติดตั้ง • เลื่อนหรือซูมแผนที่เพื่ออัปเดตชั้นข้อมูล`;el('map-layer-status').classList.toggle('error-text',failures.length>0);}
let maskData,maskPromise;async function loadMask(){if(maskLayer){map.removeLayer(maskLayer);maskLayer=null;}if(!el('map-mask').checked){el('mask-status').textContent='';return;}try{if(!maskData){maskPromise??=Promise.all([geo('mask',{tolerance:'0.002'},undefined),geo('province',{tolerance:'0.002'},undefined)]).then(([gray,prov])=>{const byName=new Map();for(const f of [...prov.features,...gray.features]){const name=f.properties.prov_nam_t||f.properties.PROV_NAM_T;if(name)byName.set(name,{...f,properties:{...f.properties,maskProvince:name}});}return {type:'FeatureCollection',features:[...byName.values()]};});maskData=await maskPromise;}if(!el('map-mask').checked)return;const p=el('map-province').value,keep=new Set(p==='all'?base.map(s=>s.province):[p]);const data={type:'FeatureCollection',features:maskData.features.filter(f=>!keep.has(f.properties.maskProvince))};if(maskLayer)map.removeLayer(maskLayer);maskLayer=L.geoJSON(data,{pane:'province-mask',interactive:false,style:{fillColor:'#293441',fillOpacity:.9,color:'#48515e',weight:.3}}).addTo(map);el('mask-status').textContent=`ซ่อนพื้นที่อื่น ${data.features.length} จังหวัด จากขอบเขตรวม ${maskData.features.length} จังหวัด (Province_Gray + ขอบเขตจังหวัด ปภ.)`;}catch(e){maskPromise=null;el('mask-status').textContent='ชั้นซ่อนจังหวัดโหลดไม่สำเร็จ: '+e.message;}}
