el('map-province').onchange=()=>{drawPoints(true);void loadMask();};el('map-class').onchange=()=>{el('map-b-cutoff-filter').hidden=el('map-class').value!=='B';drawPoints(true);};el('map-b-cutoff').onchange=()=>drawPoints(true);el('map-mask').onchange=()=>void loadMask();el('map-fit').onclick=()=>drawPoints(true);el('map-wide').onclick=()=>{const layout=document.querySelector('.map-layout'),wide=layout.classList.toggle('map-wide');el('map-wide').setAttribute('aria-pressed',String(wide));el('map-wide').textContent=wide?'แสดงแผงข้อมูล':'ขยายแผนที่';setTimeout(()=>map.invalidateSize(),0);};document.querySelectorAll('[data-layer]').forEach(control=>control.onchange=()=>{const id=control.dataset.layer,layer=layers.get(id);if(!control.checked&&layer){map.removeLayer(layer);layers.delete(id);el('state-'+id).textContent='ปิด';}void loadLayers();});
